import { execFile } from 'node:child_process';
export const EXE = '/workspace/dataset/test19_executable';
export const MK = { a:'MKAA', b:'MKBB', c:'MKCC', d:'MKDD', e:'MKEE', f:'MKFF' };
const ORDER = ['a','b','c','d','e','f'];

function runAsync(args) {
  const argv = [];
  for (const k of ORDER) argv.push('--' + k, args[k] === undefined ? MK[k] : args[k]);
  return new Promise((res) => {
    execFile(EXE, argv, { encoding: 'utf8', maxBuffer: 1 << 28 }, (err, stdout, stderr) => {
      if (err) res('ERR(' + err.code + ')\n' + (stdout || '') + (stderr || ''));
      else res(stdout);
    });
  });
}

/** async equivalent of phase('a', s) */
export async function phaseA(s) {
  const out = await runAsync({ a: s });
  const lines = out.split('\n');
  const end = lines.indexOf('<p>' + MK.b + '</p>');
  return lines.slice(0, end).join('\n');
}

/** Run a list of inputs with limited concurrency; returns array of [input, output] */
export async function batch(inputs, conc = 8) {
  const results = new Array(inputs.length);
  let i = 0;
  async function worker() {
    while (true) {
      const k = i++;
      if (k >= inputs.length) return;
      results[k] = [inputs[k], await phaseA(inputs[k])];
    }
  }
  await Promise.all(Array.from({ length: conc }, worker));
  return results;
}

export async function report(label, inputs, conc = 8) {
  const rs = await batch(inputs, conc);
  console.log('##### ' + label);
  for (const [inp, out] of rs) {
    console.log(JSON.stringify(inp) + '  =>  ' + JSON.stringify(out));
  }
}

